import{_ as i,l as o,o as e,c as s,v as t,p as d,x as l,d as n,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"双向与 ALT","description":"","frontmatter":{"title":"双向与 ALT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bidirectional-alt.md","filePath":"cs/bidirectional-alt.md","lastUpdated":1789023840000}'),c={name:"cs/bidirectional-alt.md"};function A(_,a,m,T,E,u){const r=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="双向与-alt" tabindex="-1">双向与 ALT <a class="header-anchor" href="#双向与-alt" aria-label="Permalink to &quot;双向与 ALT&quot;">​</a></h1><div class="epigraph"><p>从 $s$ 与 $t$ 同时长最短路树，在中间相遇；ALT 用少量路标的三角不等式造可行启发，把 A* 接到路网上。</p><footer>—— 据 Pohl, Bi-Directional Search, 1971；Goldberg and Harrelson, Computing the Shortest Path: A* Search Meets Graph Theory, 2005 整理</footer></div><p>上一课<a href="/cs/a-star">A*</a>要一个可采纳 \\(h\\)。路网没有曼哈顿。缺口是两件事：双向 Dijkstra/A* 减少展开；以及 ALT（A*, Landmarks, Triangle inequality）用预处理距离造 \\(h\\)。不重写一致启发的证明。后课收缩层次把预处理做进图本身。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单向 Dijkstra 展开约以 \\(s\\) 为心、半径 \\(\\delta(s,t)\\) 的球。双向：正图从 \\(s\\)、反图从 \\(t\\)，直到两侧键满足相遇条件（注意：最先碰到的点未必在最短路上，要维护 \\(\\mu\\) 上界并继续到终止规则）。正确终止比单向更脆，实现须照教材条件，不要「两侧一碰面就停」。</p><p>ALT：选路标 \\(L\\)。预处理 \\(\\delta(\\ell,\\cdot)\\)、\\(\\delta(\\cdot,\\ell)\\)。\\(h_t(v)=\\max_{\\ell}\\max\\{\\delta(v,\\ell)-\\delta(t,\\ell),\\,\\delta(\\ell,t)-\\delta(\\ell,v)\\}\\) 等三角下界。可采纳。路标越多 \\(h\\) 越紧、预处理越贵。</p><p>缺口是终止规则与路标 \\(h\\)，不是新的堆。</p><h3 id="路标不是聚类中心随便一个" tabindex="-1">路标不是聚类中心随便一个 <a class="header-anchor" href="#路标不是聚类中心随便一个" aria-label="Permalink to &quot;路标不是聚类中心随便一个&quot;">​</a></h3><p>路标应覆盖「远」方向：避开、最远点等启发式选点。随机路标也可用，效率差。不要把路标当聚类再在类内 Dijkstra——那是另一套分区。</p><p><span class="marginnote">Pohl 1971 双向。Goldberg–Harrelson 2005 ALT（Microsoft 路网）。后课 Geisberger 等 CH 用收缩，预处理更重、查询更快。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>双向：两套优先队列，交替或按 \\(f\\) 平衡展开，维护最佳相遇 \\(\\mu\\)。ALT：离线选 \\(L\\)、全源到路标；在线 A* 用 \\(h\\)。可双向+ALT。</p>',12)),(e(),d(p,null,{default:l(()=>[h(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E4%BB%8E%20s%22%5D%20--%3E%20MEET%5B%22%E7%9B%B8%E9%81%87%E4%B8%8A%E7%95%8C%20%CE%BC%22%5D%0A%20%20T%5B%22%E4%BB%8E%20t%20%E5%8F%8D%E5%9B%BE%22%5D%20--%3E%20MEET%0A%20%20LM%5B%22%E8%B7%AF%E6%A0%87%E8%B7%9D%E7%A6%BB%22%5D%20--%3E%20H%5B%22%E4%B8%89%E8%A7%92%E5%90%AF%E5%8F%91%20h%22%5D%0A%20%20H%20--%3E%20AST%5B%22A*%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>预处理空间 \\(O(|L|V)\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>三角不等式：\\(d(v,t)\\ge d(v,\\ell)-d(t,\\ell)\\)。取 \\(\\max\\) 仍可采纳。双向的正确性：最短路被切成两段，两段都最优时 \\(\\mu\\) 正确；过早停会漏更短组合。与单向 A*：双向不自动给出 \\(h\\)，只减展开半径。</p><p>负权仍禁止这套 Dijkstra 骨架。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Hub Labeling 全文。不写时间相关路网。后课默认：路网查询可双向 + 路标启发。下一课收缩层次：按序收缩顶点加捷径。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>双向要正确终止，不是第一次碰面。</li><li>ALT：路标三角不等式造 \\(h\\)。</li><li>预处理换查询；与 CH 下一课分工。</li><li>出处：Pohl, 1971；Goldberg and Harrelson, 2005。</li></ul>',8))])}const f=i(c,[["render",A]]);export{B as __pageData,f as default};
